(function(root){'use strict';let input;addEventListener('keydown',e=>{if(e.code!=='F10'||e.target.matches?.('input,textarea,select'))return;e.preventDefault();if(!input){input=document.createElement('input');input.type='file';input.accept='.json';input.multiple=true;input.hidden=true;document.body.append(input);input.onchange=async()=>{try{const reports=await Promise.all([...input.files].map(async f=>JSON.parse(await f.text()))),r=root.NeonCombat.Review144.compare(reports);let panel=document.querySelector('#compare144');if(!panel){panel=document.createElement('section');panel.id='compare144';panel.style='position:fixed;inset:10% 10%;z-index:1000;background:#07111f;color:#dff5ef;padding:24px;overflow:auto;border:1px solid #6de2c7';document.body.append(panel);}panel.replaceChildren();const close=document.createElement('button');close.textContent='Close';close.onclick=()=>panel.remove();const heading=document.createElement('h2');heading.textContent='Local playtest comparison';const pre=document.createElement('pre');pre.textContent=JSON.stringify(r,null,2);panel.append(close,heading,pre);}catch(err){alert('Cannot compare these reports: '+err.message);}finally{input.value='';}};}input.click();});})(globalThis);
